I have recently implemented community ID hashing in VRL, see the bellow VRL snippet (see here for a full config file with tests):
  . = parse_json!(.message)
  saddr = ip_aton!(to_string!(.sourceIP))
  daddr = ip_aton!(to_string!(.destIP))
  sport = to_int!(.sourcePort)
  dport = to_int!(.destPort)
  proto = to_string!(.proto)


  proto_padded = ""
  if proto == "TCP" {
    proto_padded = "0600"
  } else if proto == "UDP" {
    proto_padded = "1100"
  } else {
    log("Only TCP or UDP supported")
    abort
  }


  seed_padded = "0000"
  sport_padded = to_string(format_int!(sport, 16))
  dport_padded = to_string(format_int!(dport, 16))
  saddr_padded = to_string(format_int!(saddr, 16))
  daddr_padded = to_string(format_int!(daddr, 16))


  if length(sport_padded) < 4 {
    to_add = "0" *  (4 - length(sport_padded))
    sport_padded = to_add + sport_padded
  }

  if length(dport_padded) < 4 {
    to_add = "0" *  (4 - length(dport_padded))
    dport_padded = to_add + dport_padded
  }

  if length(daddr_padded) < 8 {
    to_add = "0" *  (8 - length(daddr_padded))
    daddr_padded = to_add + daddr_padded
  }

  if length(saddr_padded) < 8 {
    to_add = "0" *  (8 - length(saddr_padded))
    saddr_padded = to_add + saddr_padded
  }


  to_hash_base16 = ""
  if saddr < daddr {
    to_hash_base16 = seed_padded + saddr_padded + daddr_padded + proto_padded + sport_padded + dport_padded
  } else {
    to_hash_base16 = seed_padded + daddr_padded + saddr_padded + proto_padded + dport_padded + sport_padded
  }
  to_hash, err = decode_base16(to_hash_base16)
  if err != null {
    log(err)
  }
  .community_id = "1:" + encode_base64(decode_base16!(sha1(to_hash)))

It's worth noting, the above is not a complete implementation of Community IDs. It has the following issues:

It only supports UDP + TCP
It lacks support for equal IP addresses, where it should fall back to using the ports for ordering
It only supports a seed of 0

